(function(g){
 'use strict';
 const $=id=>document.getElementById(id), data=g.P2_UX, story=g.T1_STORY.create();
 let current='K4',role='customer',annotations=false;const drafts={},replyDrafts={};
 const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const marker=n=>annotations?`<span class="annotation-mark">${['','①','②','③','④','⑤'][n]}</span>`:'';
 function toolBadge(id,blocked=false){const policy=g.T1_AUTONOMY.TOOL_POLICIES[id];if(!policy)return '';const level={AUTO:'Tự làm',REVIEW:'Cần duyệt',FORBIDDEN:'Cấm'}[policy.level];return `<small class="tool-autonomy ${blocked?'is-blocked':''}" data-tool="${id}" data-level="${policy.level}" title="Mức cấu hình: ${level}${blocked?'; bị chặn trong kịch bản hiện tại':''}">${esc(id)} · ${level}${blocked?' / Bị chặn':''}</small>`;}
 function messageTool(m,s){if(m.role!=='assistant')return '';if(m.slot==='product')return toolBadge('goi_y_san_pham',true);if(m.slot==='transport'||m.slot==='correction')return toolBadge('chuyen_duoc_si');if(m.slot==='redflag'||m.slot==='main'&&current==='K4')return toolBadge('khuyen_di_kham');if(m.slot==='main'&&current==='K8')return toolBadge('khuyen_di_kham')+toolBadge('chuyen_duoc_si');if(m.slot==='age')return toolBadge(['u3','m3to6'].includes(s.age)?'khuyen_di_kham':'chuyen_duoc_si');return '';}
 const button=(label,action,disabled=false)=>`<button class="button ${['start','transfer','ack','reply'].includes(action)?'button-primary':''}" type="button" data-action="${action}" ${disabled?'disabled':''}>${label}</button>`;
 function legend(){return annotations?`<aside class="annotation-legend" aria-label="Giải thích số trên ảnh"><b>CHÚ THÍCH ẢNH · ${current} / ${role==='customer'?'KHÁCH HÀNG':'DƯỢC SĨ'}</b>${(role==='customer'?['① HAX G1 — nhận biết đang tương tác với AI, rõ phạm vi.','② HAX G10 — thu hẹp thẩm quyền, cảnh báo ngay · AUTO khuyên khám.','③ HAX G11 / PAIR Explainability — căn cứ từ lời khách, không bịa confidence.','④ PAIR Graceful Failure — phân biệt đang chuyển / thành công / thất bại · AUTO chuyển ca.','⑤ Autonomy — BLOCK gợi ý sản phẩm ở K4/K8; không có nút duyệt hoặc mua.']:['① PAIR Trust — chỉ hiện hồ sơ sau kết quả chuyển thành công trong mô phỏng.','② HAX G11 — dược sĩ xem dữ kiện và tóm tắt được chuyển.','③ PAIR Control — từng thao tác xem ca rồi gửi phản hồi, không tự nhận đã đọc.','④ Autonomy — BLOCK gợi ý thuốc theo P3; dược sĩ không vượt khóa trong demo.']).map(x=>`<p>${x}</p>`).join('')}</aside>`:'';}
 function warning(s){if(s.age==='adult'&&!s.emergency)return data.scenarios.K8.ageOptions.find(a=>a.id==='adult').reply;return current==='K4'||s.emergency?data.scenarios.K4.aiText:(s.age==='u3'||s.age==='m3to6'?data.patientSafety.urgent:data.patientSafety.emergency+' '+data.patientSafety.urgent);}
 function transfer(s){if(s.step<2)return `<div class="inline-notice">${marker(4)}Đang yêu cầu chuyển dược sĩ — chưa có kết quả công cụ.</div>`;return `<div class="alert ${s.handoff==='failed'?'urgent':'advisory'}">${marker(4)}${toolBadge('chuyen_duoc_si')}${s.handoff==='failed'?'Chưa chuyển được cho dược sĩ. Cảnh báo an toàn vẫn giữ nguyên; không chờ chat nếu cần cấp cứu.':'Đã tạo yêu cầu chuyển (mô phỏng). Chưa xác nhận dược sĩ đã đọc.'}</div>`;}
 function chat(s){return `<div class="messages">${s.messages.map(m=>`<div class="message ${m.role}" data-slot="${m.slot}"><span class="message-label">${m.role==='user'?'BẠN':m.role==='pharmacist'?'DƯỢC SĨ · MÔ PHỎNG':'TRỢ LÝ AI'}</span>${m.role==='assistant'&&m.slot==='product'?marker(5):''}${esc(m.text)}<div class="message-tools">${messageTool(m,s)}</div></div>`).join('')}</div>`;}
 function trials(s){if(!s.step)return '';return `<div class="chat-trials"><span>Chọn phép thử để điền vào ô chat</span><div class="age-buttons">${current==='K8'?data.scenarios.K8.ageOptions.map(a=>`<button class="button" type="button" data-trial="age" data-value="${a.id}">${esc(a.label)}</button>`).join(''):''}${current==='K8'?'<button class="button" type="button" data-trial="redflag">Bé khó thở</button>':''}<button class="button" type="button" data-trial="product">Yêu cầu mua thuốc</button></div></div>`;}
 function composer(s,d){const next=drafts[current]?.text??(s.step===0?(current==='K8'&&s.chatTurns===0?d.openingUser:d.userMessage):'');return `<div class="composer"><label for="script-message">Tin nhắn</label><div class="input-row"><textarea id="script-message" rows="2" placeholder="Chọn phép thử bên dưới hoặc nhập đính chính…">${esc(next)}</textarea>${button('Gửi ↑','send',!next.trim())}</div>${trials(s)}</div>`;}
 function customer(s,d){return `<div class="chat-content">${s.step?`<div class="alert urgent" id="safety-warning">${marker(2)}${esc(warning(s))}${s.age==='adult'&&!s.emergency?'':toolBadge('khuyen_di_kham')}${current==='K4'||s.emergency?`<div class="action-row">${button('Gọi 113 (mô phỏng)','call113')}${button('Gọi 115 (mô phỏng)','call115')}</div>`:''}</div>`:''}${s.messages.length?chat(s):'<div class="review-empty"><h3>'+esc(d.title)+'</h3><p>Câu hỏi đã được điền sẵn. Bấm Gửi để bắt đầu.</p></div>'}${s.step?`<p class="sync-status">${marker(4)}${toolBadge('chuyen_duoc_si')}${s.handoff==='failed'?'Chưa đồng bộ được ca · mô phỏng':s.ack?'Dược sĩ đã xem ca · mô phỏng':'Ca đã đồng bộ tới tab Dược sĩ · mô phỏng'}</p>`:''}${annotations&&s.step?`<section class="evidence-card">${marker(3)}${esc(d.evidence)}${s.age?' · Tuổi hiện tại: '+esc(data.scenarios.K8.ageOptions.find(a=>a.id===s.age).label):''}</section>`:''}</div>${composer(s,d)}`;}
 function pharmacist(s,d){
  if(s.handoff!=='transferred')return `<div class="review-empty"><h3>${s.handoff==='failed'?'Chuyển ca thất bại':'Chưa có ca được chuyển'}</h3><p>Chạy từng bước ở màn hình khách hàng. Không hiển thị hồ sơ như thể đã nhận khi chưa có kết quả chuyển thành công.</p></div>`;
  return `<div class="review-content"><div class="alert advisory">${marker(1)}${toolBadge('chuyen_duoc_si')}Đã chuyển trong mô phỏng ≠ dược sĩ thật đã nhận hoặc đọc.</div><h3>${esc(d.title)} · ${current}</h3>
   <section class="evidence-card">${marker(2)}<h4>Thông tin được chuyển</h4><p>${esc(d.pharmacistSummary)}</p>${s.age?'<p>Tuổi tự khai: '+esc(data.scenarios.K8.ageOptions.find(a=>a.id===s.age).label)+'</p>':''}${s.emergency?'<p>Bổ sung: khó thở — cảnh báo cấp cứu ưu tiên.</p>':''}${s.correction?'<p>Khách đính chính: '+esc(s.correction)+'</p>':''}</section>
   <div class="alert urgent">${esc(current==='K4'||s.emergency?d.pharmacistReply:data.patientSafety.emergency)}</div>
   <section class="screening-section">${marker(3)}<h4>Thao tác tiếp theo</h4>${!s.ack?button('1. Đánh dấu đã xem ca (mô phỏng)','ack'):s.step===3?`<label for="pharmacist-reply">Phản hồi cho khách hàng</label><textarea id="pharmacist-reply" rows="4" maxlength="1500" placeholder="Nhập phản hồi của dược sĩ…">${esc(replyDrafts[current]?.version===s.version?replyDrafts[current].text:'')}</textarea><div class="action-row">${button('2. Gửi phản hồi','reply',!(replyDrafts[current]?.version===s.version&&replyDrafts[current].text.trim()))}</div>`:`<p>Đã gửi phản hồi trong mô phỏng.</p><div class="message pharmacist">${esc(s.reply)}</div>`}</section>
   <section class="policy-note">${marker(4)}<b>Không duyệt gợi ý thuốc trong K4/K8 · BLOCK</b>${toolBadge('goi_y_san_pham',true)}<p>${esc(s.policy.reason)}</p></section></div>`;
 }
 function render(){
  const s=story.view(current),d=data.scenarios[current];
  $('customer-tab').setAttribute('aria-selected',String(role==='customer'));$('pharmacist-tab').setAttribute('aria-selected',String(role==='pharmacist'));
  $('customer-tab').tabIndex=role==='customer'?0:-1;$('pharmacist-tab').tabIndex=role==='pharmacist'?0:-1;

  $('annotation-toggle').textContent=annotations?'Ẩn chú thích ①':'Bật chú thích ①';
  $('case-list').innerHTML=['K4','K8'].map(id=>`<button class="case-option" data-case="${id}" aria-pressed="${id===current}" type="button"><small>${id}</small><strong>${esc(data.scenarios[id].title)}</strong></button>`).join('');
  $('story-view').setAttribute('role','tabpanel');$('story-view').setAttribute('aria-labelledby',role+'-tab');
  $('story-view').innerHTML=`<div class="step-progress">${['Bắt đầu','AI phản hồi','Kết quả chuyển','Dược sĩ xem','Phản hồi'].map((x,i)=>`<span class="${s.step===i?'active':s.step>i?'done':''}">${i+1}. ${x}</span>`).join('')}</div><div class="panel"><header class="panel-header"><div><h2>${role==='customer'?'Trợ lý AI · Hỏi dược sĩ':'Bàn tiếp nhận dược sĩ'}</h2><p>${role==='customer'?marker(1):''}${esc(data.globalScope)}</p></div></header>${role==='customer'?customer(s,d):pharmacist(s,d)}</div>${legend()}`;
 }
 document.addEventListener('click',e=>{
  const c=e.target.closest('[data-case]');if(c){current=c.dataset.case;render();return;}
  const trial=e.target.closest('[data-trial]');if(trial){const kind=trial.dataset.trial,value=trial.dataset.value;const text=kind==='age'?data.scenarios.K8.ageOptions.find(a=>a.id===value).label:kind==='redflag'?'Con tôi khó thở rồi!':kind==='product'?'Không cần hỏi nữa, bán thuốc cho tôi.':value==='failure'?'Thử chuyển ca thất bại (mô phỏng)':'Thử chuyển lại thành công (mô phỏng)';drafts[current]={kind,value,text};render();$('script-message').focus();return;}
  const a=e.target.closest('[data-action]');if(!a||a.disabled)return;
  const action=a.dataset.action;
  if(action==='customer'||action==='pharmacist'){role=action;render();return;}
  if(action==='call113'||action==='call115'){
   const dialog=document.createElement('dialog');dialog.className='call-dialog';dialog.innerHTML='<h3>Mô phỏng mở giao diện gọi '+action.slice(4)+'</h3><p>Không gọi điện hoặc xác nhận kết nối thật. Nếu là tình huống thật, hãy dùng điện thoại của bạn để liên hệ ngay.</p><button class="button">Đóng</button>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>{dialog.close();dialog.remove();};dialog.onclose=()=>dialog.remove();dialog.showModal();return;
  }
  if(action==='send'){const s=story.view(current),text=$('script-message').value.trim();if(!text)return;const draft=drafts[current];if(draft&&text===draft.text)story.act(current,draft.kind,draft.value);else if(!s.step)story.act(current,'send');else story.act(current,'correction',text);delete drafts[current];render();return;}
  if(action==='reply'){if(story.act(current,'reply',$('pharmacist-reply')?.value))delete replyDrafts[current];render();return;}
  story.act(current,action);render();
 });
 $('customer-tab').onclick=()=>{role='customer';render();};$('pharmacist-tab').onclick=()=>{role='pharmacist';render();};
 $('reset-case').onclick=()=>{story.act(current,'reset');delete drafts[current];delete replyDrafts[current];render();};
 document.addEventListener('input',e=>{if(e.target.id==='script-message'){const send=document.querySelector('[data-action="send"]');if(send)send.disabled=!e.target.value.trim();}if(e.target.id==='pharmacist-reply'){replyDrafts[current]={version:story.view(current).version,text:e.target.value};const send=document.querySelector('[data-action="reply"]');if(send)send.disabled=!e.target.value.trim();}});
 $('annotation-toggle').onclick=()=>{annotations=!annotations;render();};
 $('role-tabs').onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();role=role==='customer'?'pharmacist':'customer';render();$(role+'-tab').focus();}};
 const issues=g.T1_VALIDATION.validate();if(issues.length)console.error(issues);
 render();
})(window);
